import { describe, expect, it } from 'vitest';
import { Add, Basic, Mul, Rational, add, flatten, rebuild, symbols, unpack } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.strategies.rl", () => {
  // no value
  //   rl(Add(x, -x, 3*x, 2, 3, evaluate=False))
  //   => 3*x + 5
  it.todo("rl(Add(x, -x, 3*x, 2, 3, evaluate=False))");
  it("unpack(Basic(S(2)))", () => {
    expect(sympyStr(unpack(Basic(Rational.of(2n, 1n, { gcd: 1n }))))).toBe('2');
  });
  it("expr", () => {
    const [x, y] = symbols('x y');
    expect(sympyStr(new Mul([Rational.of(2n, 1n, { gcd: 1n }), add(x, y)]))).toBe('2*(x + y)');
  });
});

describe("sympy/strategies/tests/test_rl.py", () => {
  it("test_flatten:36", () => {
    expect(sympyStr(flatten(Basic(Rational.of(1n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n }), Basic(Rational.of(3n, 1n, { gcd: 1n }), Rational.of(4n, 1n, { gcd: 1n })))))).toBe('Basic(1, 2, 3, 4)');
  });
  it("test_unpack:41", () => {
    expect(sympyStr(unpack(Basic(Rational.of(2n, 1n, { gcd: 1n }))))).toBe('2');
  });
  it("test_unpack:42", () => {
    expect(sympyStr(unpack(Basic(Rational.of(2n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }))))).toBe('Basic(2, 3)');
  });
  it("test_rebuild:78", () => {
    expect(sympyStr(rebuild(new Add([Rational.of(1n, 1n, { gcd: 1n }), Rational.of(2n, 1n, { gcd: 1n })])))).toBe('3');
  });
});
